transforms.code:
if value['assetId']: return system.kanoa.asset.getAssetTagPath({'assetId': value['assetId']})
if value['assetPath']: return system.kanoa.asset.getAssetTagPath({'assetPath': value['assetPath']})
return None

#With a dashboard date selector: the range's OEE, counts and times as system.kanoa.event.getOEESummary works them out.
#None without one (the KPI shows the asset's live OEE tags)
filters = value or {}
dateRange = filters.get('dateRange')
if not dateRange or not filters.get('assetId') or filters.get('ignoreDateRange'):
	return None
rows = system.kanoa.utilities.convertDatasetToJSON(system.kanoa.event.getOEESummary({'assetId': filters['assetId'],
			'startDate': dateRange['startDate'], 'endDate': dateRange['endDate']}))
return rows[0] if rows else {}
